parameters.jsCode:
const body = $input.first().json.body || $input.first().json || {};
const message = (body.message || '').trim();
const sessionId = body.sessionId || 'admin-hub-' + Date.now();
const adminName = body.adminName || 'Administrador';
const action = body.action || 'general';

// Contexto de la plataforma enviado desde el frontend
const context = body.context || {};
const usersData = JSON.stringify(context.users || []);
const reviewsData = JSON.stringify(context.reviews || []);
const releasesData = JSON.stringify(context.releases || []);
const labelsData = JSON.stringify(context.labels || []);
const vinylsData = JSON.stringify(context.vinyls || []);
const reportsData = JSON.stringify(context.reports || []);

const promptText = `Instrucción del Administrador (${adminName}):
"${message}"

Acción solicitada: ${action}

--- DATOS COMPLETOS DE LA PLATAFORMA SONAR ---
Usuarios registrados (${(context.users || []).length}): ${usersData}
Reseñas (${(context.reviews || []).length}): ${reviewsData}
Lanzamientos destacados (${(context.releases || []).length}): ${releasesData}
Sellos discográficos (${(context.labels || []).length}): ${labelsData}
Ediciones de Vinilo (${(context.vinyls || []).length}): ${vinylsData}
Reportes de conducta (${(context.reports || []).length}): ${reportsData}`;

return [
  {
    json: {
      message,
      sessionId,
      adminName,
      action,
      promptText,
      timestamp: new Date().toISOString()
    }
  }
];

const input = $input.first().json || {};
const prev = $('Preparar Contexto Admin').first().json || {};

let rawOutput = '';
if (typeof input.output === 'string') {
  rawOutput = input.output;
} else if (input.output && typeof input.output.text === 'string') {
  rawOutput = input.output.text;
} else if (typeof input.text === 'string') {
  rawOutput = input.text;
} else if (typeof input.response === 'string') {
  rawOutput = input.response;
} else if (typeof input === 'string') {
  rawOutput = input;
} else {
  rawOutput = String(input.output || 'Admin Hub IA no pudo generar una respuesta.');
}

let metadata = {};
let quickActions = [];
let cleanMessage = rawOutput;

// Extraer bloque JSON de metadatos
const jsonMatch = rawOutput.match(/```(?:json)?([\s\S]*?)```/);
if (jsonMatch) {
  try {
    const parsed = JSON.parse(jsonMatch[1].trim());
    metadata = {
      category: parsed.category || 'mixed',
      severity: parsed.severity || 'info',
      metrics: parsed.metrics || {}
    };
    if (Array.isArray(parsed.quickActions)) {
      quickActions = parsed.quickActions;
    }
    cleanMessage = rawOutput.replace(/```(?:json)?[\s\S]*?```/, '').trim();
  } catch (e) {
    // JSON inválido, mantener texto completo
  }
}

return [
  {
    json: {
      success: true,
      analysis: cleanMessage,
      metadata,
      quickActions,
      action: prev.action || 'general',
      sessionId: prev.sessionId || 'admin-hub-default',
      timestamp: new Date().toISOString(),
      model: 'gemini-1.5-flash'
    }
  }
];

